using System;
using System.Collections.Generic;
using UnityEngine;

namespace GroundCrew.Aircraft
{
    public enum MovingPartKind { Door, Control, Fan, Steering, Wheel }

    /// <summary>
    /// Runtime controller for an aircraft generated by GroundCrewVR/Tools/AircraftGenerator.
    ///
    /// Put it on the root of the imported .glb. On Awake it finds every moving part (doors,
    /// cargo doors, exits, flaps, ailerons, elevators, rudder, fans, nose-gear steering, wheels)
    /// from the empty helper nodes the generator writes (HingeEnd / TestPoint / OpenHint), so it
    /// works whatever axis convention the glTF importer uses. It also builds the LODGroup and
    /// drives the exterior lights.
    ///
    /// Every LOD contains the same named parts; the rig moves all copies together.
    /// "Open" means: door open, flap/aileron/elevator trailing edge down, wheel rolling forward.
    /// </summary>
    [DisallowMultipleComponent]
    public class AircraftRig : MonoBehaviour
    {
        [SerializeField, Tooltip("Optional <AircraftId>.json sidecar from the generator; supplies exact door limits.")]
        TextAsset definition;

        [SerializeField] bool setupLods = true;
        [SerializeField] float[] lodScreenHeights = { 0.30f, 0.08f, 0.012f };

        [SerializeField, Tooltip("Degrees per second when animating towards a target.")]
        float doorSpeed = 40f;
        [SerializeField] float controlSurfaceSpeed = 30f;

        [SerializeField] float beaconFlashHz = 1f;

        public class MovingPart
        {
            public string Name;
            public MovingPartKind Kind;
            public Transform Transform;
            public Vector3 Axis;
            public float OpenSign;
            public Quaternion Rest;
            public float Min;
            public float Max;
            public float Angle;
            public float Target;
            public float WheelRadius;
        }

        readonly Dictionary<string, List<MovingPart>> m_Parts = new Dictionary<string, List<MovingPart>>();
        readonly List<GameObject> m_Beacons = new List<GameObject>();
        readonly List<GameObject> m_NavLights = new List<GameObject>();
        readonly List<Light> m_FlightDeckLights = new List<Light>();
        bool m_BeaconOn;
        bool m_Discovered;

        public IEnumerable<string> PartNames => m_Parts.Keys;
        public bool BeaconOn => m_BeaconOn;

        /// <summary>Fan speed in revolutions per minute (visual only).</summary>
        public float FanRpm { get; set; }

        void Awake()
        {
            Discover();
            if (setupLods) SetupLods();
            SetBeacon(false);
            SetFlightDeckLight(false);   // Quest budget: one real-time light; switch on when needed
        }

        // ------------------------------------------------------------------ discovery

        void Discover()
        {
            if (m_Discovered) return;
            m_Discovered = true;

            foreach (var t in GetComponentsInChildren<Transform>(true))
            {
                if (t.name.StartsWith("Beacon_", StringComparison.Ordinal)) m_Beacons.Add(t.gameObject);
                else if (t.name.StartsWith("NavLight_", StringComparison.Ordinal) || t.name.StartsWith("Strobe_", StringComparison.Ordinal)) m_NavLights.Add(t.gameObject);
                else if (t.name.StartsWith("FlightDeckLight", StringComparison.Ordinal)) m_FlightDeckLights.AddRange(t.GetComponentsInChildren<Light>(true));

                if (!t.name.StartsWith("HingeEnd", StringComparison.Ordinal)) continue;
                var part = t.parent;
                var test = FindChild(part, "TestPoint");
                var hint = FindChild(part, "OpenHint");
                if (part == null || test == null || hint == null) continue;

                // Everything here is in the part's local space; the part rests at its import rotation.
                var axis = t.localPosition.normalized;
                var plus = Quaternion.AngleAxis(10f, axis) * test.localPosition;
                var minus = Quaternion.AngleAxis(-10f, axis) * test.localPosition;
                var sign = (plus - hint.localPosition).sqrMagnitude <= (minus - hint.localPosition).sqrMagnitude ? 1f : -1f;

                var mp = new MovingPart
                {
                    Name = part.name,
                    Kind = KindFromName(part.name),
                    Transform = part,
                    Axis = axis,
                    OpenSign = sign,
                    Rest = part.localRotation,
                };
                DefaultLimits(mp);
                if (mp.Kind == MovingPartKind.Wheel) mp.WheelRadius = EstimateRadius(part);

                if (!m_Parts.TryGetValue(mp.Name, out var list))
                {
                    list = new List<MovingPart>();
                    m_Parts.Add(mp.Name, list);
                }
                list.Add(mp);
            }

            ApplyDefinitionLimits();
        }

        static Transform FindChild(Transform parent, string prefix)
        {
            if (parent == null) return null;
            foreach (Transform c in parent)
                if (c.name.StartsWith(prefix, StringComparison.Ordinal)) return c;
            return null;
        }

        static MovingPartKind KindFromName(string n)
        {
            if (n.StartsWith("Fan_", StringComparison.Ordinal)) return MovingPartKind.Fan;
            if (n.StartsWith("NoseGear_Steer", StringComparison.Ordinal)) return MovingPartKind.Steering;
            if (n.Contains("_Wheel_")) return MovingPartKind.Wheel;
            if (n.StartsWith("Flap_", StringComparison.Ordinal) || n.StartsWith("Aileron", StringComparison.Ordinal) ||
                n.StartsWith("Elevator", StringComparison.Ordinal) || n.StartsWith("Rudder", StringComparison.Ordinal))
                return MovingPartKind.Control;
            return MovingPartKind.Door;
        }

        static void DefaultLimits(MovingPart p)
        {
            var n = p.Name;
            switch (p.Kind)
            {
                case MovingPartKind.Door: p.Min = 0f; p.Max = 90f; break;
                case MovingPartKind.Steering: p.Min = -78f; p.Max = 78f; break;
                case MovingPartKind.Control:
                    if (n.StartsWith("Flap_", StringComparison.Ordinal)) { p.Min = 0f; p.Max = 40f; }
                    else if (n.StartsWith("Aileron", StringComparison.Ordinal)) { p.Min = -20f; p.Max = 20f; }
                    else if (n.StartsWith("Elevator", StringComparison.Ordinal)) { p.Min = -25f; p.Max = 20f; }
                    else { p.Min = -27f; p.Max = 27f; }
                    break;
                default: p.Min = float.NegativeInfinity; p.Max = float.PositiveInfinity; break;
            }
        }

        static float EstimateRadius(Transform wheel)
        {
            var renderers = wheel.GetComponentsInChildren<Renderer>(true);
            var r = 0f;
            foreach (var rend in renderers) r = Mathf.Max(r, rend.bounds.extents.y);
            return r > 0.05f ? r : 0.5f;
        }

#pragma warning disable 0649 // filled by JsonUtility
        [Serializable] class DefinitionFile { public MovingPartDef[] movingParts; }
        [Serializable] class MovingPartDef { public string path; public float minAngle; public float maxAngle; }
#pragma warning restore 0649

        void ApplyDefinitionLimits()
        {
            if (definition == null) return;
            DefinitionFile file;
            try { file = JsonUtility.FromJson<DefinitionFile>(definition.text); }
            catch (Exception e) { Debug.LogWarning($"[AircraftRig] Could not read {definition.name}: {e.Message}", this); return; }
            if (file?.movingParts == null) return;

            foreach (var def in file.movingParts)
            {
                if (string.IsNullOrEmpty(def.path)) continue;
                var name = def.path.Substring(def.path.LastIndexOf('/') + 1);
                if (!m_Parts.TryGetValue(name, out var list)) continue;
                foreach (var p in list)
                {
                    if (p.Kind != MovingPartKind.Door && p.Kind != MovingPartKind.Control && p.Kind != MovingPartKind.Steering) continue;
                    p.Min = def.minAngle;
                    p.Max = def.maxAngle;
                }
            }
        }

        void SetupLods()
        {
            if (GetComponent<LODGroup>() != null) return;
            var lods = new List<LOD>();
            for (var i = 0; i < lodScreenHeights.Length; i++)
            {
                var group = FindChild(transform, "LOD" + i);
                if (group == null) break;
                lods.Add(new LOD(lodScreenHeights[i], group.GetComponentsInChildren<Renderer>(true)));
            }
            if (lods.Count < 2) return;
            var lodGroup = gameObject.AddComponent<LODGroup>();
            lodGroup.SetLODs(lods.ToArray());
            lodGroup.RecalculateBounds();
        }

        // ------------------------------------------------------------------ API

        public bool HasPart(string name) => m_Parts.ContainsKey(name);

        public IEnumerable<string> PartsOfKind(MovingPartKind kind)
        {
            foreach (var pair in m_Parts)
                if (pair.Value.Count > 0 && pair.Value[0].Kind == kind) yield return pair.Key;
        }

        /// <summary>Set a part's angle immediately (degrees, clamped to its limits).</summary>
        public bool SetAngle(string name, float degrees)
        {
            if (!m_Parts.TryGetValue(name, out var list)) return false;
            foreach (var p in list)
            {
                p.Target = Clamp(p, degrees);
                Apply(p, p.Target);
            }
            return true;
        }

        /// <summary>Animate a part towards an angle (degrees).</summary>
        public bool AnimateTo(string name, float degrees)
        {
            if (!m_Parts.TryGetValue(name, out var list)) return false;
            foreach (var p in list) p.Target = Clamp(p, degrees);
            return true;
        }

        /// <summary>0 = closed / neutral (min), 1 = fully open (max). Animated.</summary>
        public bool SetOpen01(string name, float t)
        {
            if (!m_Parts.TryGetValue(name, out var list) || list.Count == 0) return false;
            var p = list[0];
            return AnimateTo(name, Mathf.Lerp(Mathf.Max(p.Min, 0f), p.Max, Mathf.Clamp01(t)));
        }

        public float GetOpen01(string name)
        {
            if (!m_Parts.TryGetValue(name, out var list) || list.Count == 0) return 0f;
            var p = list[0];
            return Mathf.InverseLerp(Mathf.Max(p.Min, 0f), p.Max, p.Angle);
        }

        public void SetAllDoors(float t)
        {
            foreach (var name in new List<string>(PartsOfKind(MovingPartKind.Door))) SetOpen01(name, t);
        }

        /// <summary>No-argument version for UnityEvents (buttons).</summary>
        public void ToggleAllDoors()
        {
            var anyOpen = false;
            foreach (var name in PartsOfKind(MovingPartKind.Door))
                if (GetOpen01(name) > 0.05f) { anyOpen = true; break; }
            SetAllDoors(anyOpen ? 0f : 1f);
        }

        public void SetFlaps(float t)
        {
            foreach (var name in new List<string>(PartsOfKind(MovingPartKind.Control)))
                if (name.StartsWith("Flap_", StringComparison.Ordinal)) SetOpen01(name, t);
        }

        public void ToggleFlaps()
        {
            var down = false;
            foreach (var name in PartsOfKind(MovingPartKind.Control))
                if (name.StartsWith("Flap_", StringComparison.Ordinal) && GetOpen01(name) > 0.05f) { down = true; break; }
            SetFlaps(down ? 0f : 0.375f); // flaps 15 of 40
        }

        /// <summary>Nose-wheel steering angle in degrees (positive = towards the aircraft's left).</summary>
        public void SetSteering(float degrees)
        {
            foreach (var name in new List<string>(PartsOfKind(MovingPartKind.Steering))) SetAngle(name, degrees);
        }

        /// <summary>Roll all wheels by a distance in metres (negative = rolling backwards, e.g. pushback).</summary>
        public void RollWheels(float metres)
        {
            foreach (var pair in m_Parts)
            foreach (var p in pair.Value)
            {
                if (p.Kind != MovingPartKind.Wheel) continue;
                Apply(p, p.Angle + metres / p.WheelRadius * Mathf.Rad2Deg);
            }
        }

        public void SetBeacon(bool on)
        {
            m_BeaconOn = on;
            if (!on) foreach (var b in m_Beacons) if (b != null) b.SetActive(false);
        }

        public void ToggleBeacon() => SetBeacon(!m_BeaconOn);

        public void SetNavLights(bool on)
        {
            foreach (var n in m_NavLights) if (n != null) n.SetActive(on);
        }

        /// <summary>The flight-deck dome light (a point light imported from the .glb, if glTFast created one). Off at start.</summary>
        public bool FlightDeckLightOn => m_FlightDeckLights.Count > 0 && m_FlightDeckLights[0] != null && m_FlightDeckLights[0].enabled;

        public void SetFlightDeckLight(bool on)
        {
            foreach (var l in m_FlightDeckLights) if (l != null) l.enabled = on;
        }

        public void ToggleFlightDeckLight() => SetFlightDeckLight(!FlightDeckLightOn);

        // ------------------------------------------------------------------ update

        void Update()
        {
            var dt = Time.deltaTime;
            foreach (var pair in m_Parts)
            foreach (var p in pair.Value)
            {
                if (p.Kind == MovingPartKind.Fan)
                {
                    if (FanRpm != 0f) Apply(p, p.Angle + FanRpm * 6f * dt);
                    continue;
                }
                if (p.Kind == MovingPartKind.Wheel || Mathf.Approximately(p.Angle, p.Target)) continue;
                var speed = p.Kind == MovingPartKind.Door ? doorSpeed : controlSurfaceSpeed;
                Apply(p, Mathf.MoveTowards(p.Angle, p.Target, speed * dt));
            }

            if (m_BeaconOn)
            {
                // Anti-collision beacon: short red flash once per cycle.
                var lit = Mathf.Repeat(Time.time * beaconFlashHz, 1f) < 0.18f;
                foreach (var b in m_Beacons)
                    if (b != null && b.activeSelf != lit) b.SetActive(lit);
            }
        }

        static float Clamp(MovingPart p, float degrees) => Mathf.Clamp(degrees, p.Min, p.Max);

        static void Apply(MovingPart p, float degrees)
        {
            if (p.Kind == MovingPartKind.Fan || p.Kind == MovingPartKind.Wheel) degrees = Mathf.Repeat(degrees, 360f);
            p.Angle = degrees;
            p.Transform.localRotation = p.Rest * Quaternion.AngleAxis(p.OpenSign * degrees, p.Axis);
        }
    }
}
